+            Ok(())
+        }
+
+        fn end_string<W: ?Sized + io::Write>(&mut self, _writer: &mut W) -> io::Result<()> {
+            Ok(())
+        }
+    }
+
+    Serializer::with_formatter(out, FragmentFormatter)
+        .serialize_str(text)
+        .expect("a string serializes");
